import{_ as a,o as r,c as t,j as l,a as o,G as p,aa as c,B as d}from"./chunks/framework.VLjJFeoF.js";const _=JSON.parse('{"title":"性能优化","description":"","frontmatter":{},"headers":[],"relativePath":"docs/interview/performance/perf.md","filePath":"docs/interview/performance/perf.md","lastUpdated":1769531044000}'),s={name:"docs/interview/performance/perf.md"};function n(u,e,h,b,m,f){const i=d("ArticleMetadata");return r(),t("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1769531044000"},[e[0]||(e[0]=l("h1",{id:"性能优化",tabindex:"-1"},[o("性能优化 "),l("a",{class:"header-anchor",href:"#性能优化","aria-label":'Permalink to "性能优化"'},"​")],-1)),p(i,{article:{}}),e[1]||(e[1]=c('<h2 id="_1-从输入-url-到页面显示发生了什么" tabindex="-1">1.从输入 URL 到页面显示发生了什么 <a class="header-anchor" href="#_1-从输入-url-到页面显示发生了什么" aria-label="Permalink to &quot;1.从输入 URL 到页面显示发生了什么&quot;">​</a></h2><p>以 performance timeline 为主线：</p><ul><li>redirect：避免不必要的重定向（301 永久/302 临时）</li><li>cache：HTTP 缓存(强缓存/协商缓存)</li><li>dns 查询</li><li>tcp 握手：包括 ssl 握手，https，三握四挥</li></ul><p>请求优化：TTFB(Time To First Byte)：首字节时间</p><ul><li>避免重定向</li><li>dns-prefetch/preconnect</li><li>使用 CDN，使用 HTTP2</li></ul><p>渲染优化：CRP 关键渲染路径</p><ul><li>js 会阻塞 HTML 解析</li><li>css 会阻塞渲染树的形成</li><li>怎么减少回流重绘</li></ul><h2 id="_2-性能优化的手段" tabindex="-1">2.性能优化的手段 <a class="header-anchor" href="#_2-性能优化的手段" aria-label="Permalink to &quot;2.性能优化的手段&quot;">​</a></h2><p>所谓性能优化，就是从用户请求到页面显示的整个生命周期上的优化。</p><p>大体过程分为：</p><ul><li><strong>网络请求部分</strong>：查找缓存、DNS 解析、TCP 连接、HTTP 请求（会排队）和响应</li><li><strong>浏览器渲染部分</strong>：浏览器解析渲染</li></ul><p>性能优化首先要有指标去评估,通过下面的手段去优化：</p><p><strong>网络请求优化：</strong></p><p>网络请求优化的目标：减少请求数量和耗时</p><ol><li>设置静态资源的 HTTP 缓存（强缓存/协商缓存）</li><li><code>preload</code>（预先请求当前页面需要的资源）、 <code>prefetch</code>（将来页面中使用的资源，可能会浪费资源） 将数据缓存到 HTTP 缓存中</li><li>使用 <code>dns-prefetch</code>，进行 DNS 预解析</li><li>使用 <code>preconnect</code>，提前建立连接</li><li>域名分片、HTTP2（同一个域名最多处理 6 个 TCP 连接，HTTP 请求会排队）</li><li>采用 CDN 加速加快访问速度。(指派最近、高度可用)</li></ol><p><strong>静态资源体积优化</strong>：</p><ul><li>JS/CSS 的压缩，减少体积</li><li>图片: <ul><li>选择合适的格式：jpg/png/svg/webp/gif</li><li>响应式图片 （img srcset /  picture source）</li><li>小图使用 base64，减少请求，还有雪碧图（backgroud-positon）</li><li>图片懒加载</li></ul></li></ul><p><strong>渲染优化：</strong></p><blockquote><p>**渲染过程：**JavaScript 处理-&gt;计算样式-&gt;页面布局-&gt;绘制-&gt;合成</p></blockquote><ul><li><p>JS 阻塞 DOM 解析，放在body底部(使用defer(DCL 之前) /async)；css放在head</p></li><li><p>CSS 选择器减少层数，减少使用通配符。</p></li><li><p>减少重排和重绘，目标：减少直接操作 dom 的次数 重排：几何属性、获取某些特定的属性值；</p><p>重绘：修改样式</p><ul><li>合并对 DOM/样式 的操作：DocumentFragment</li><li>脱离文档流</li><li>图片定宽高</li><li>CSS3 的 GPU 加速（transform/opcity/filter/will-change）</li></ul></li><li><p>使用事件委托</p></li><li><p>事件的防抖和节流</p></li></ul><p>技术：</p><ul><li><p>虚拟滚动</p></li><li><p>懒加载：使用<code>IntersectionObserver</code> 交叉观察器</p></li><li><p>使用<code>webworker</code>处理长任务、时间切片</p></li><li><p><code>requestAnimationFrame</code> 按帧执行，做动画</p></li><li><p><code>requestIdleCallback</code> 利用每帧的空余时机</p></li></ul><h2 id="_3-webpack-构建优化手段" tabindex="-1">3. Webpack 构建优化手段 <a class="header-anchor" href="#_3-webpack-构建优化手段" aria-label="Permalink to &quot;3. Webpack 构建优化手段&quot;">​</a></h2><p>体积优化：使用 webpack-bundle-analyzer 分析打包文件的体积和构成</p><ul><li>代码压缩</li><li>剔除无用依赖， 如 moment</li><li>路由懒加载 import</li><li>分包</li><li>externals 配合，cdn 引入</li></ul><p>速度优化：使用 smp(speed-measure-webpack-plugin) 或 webpackbar 分析耗时</p><ul><li>缩小构建范围：比如配置babel-loader 不解析 node_modules</li><li>减少文件搜索范围：配置路径别名 等</li><li>并行： thread-loader，terser-webpack-plugin 开启 parallel</li><li>利用原生语言框架，使用 esbuild-loader，提高转译速度</li><li>缓存： <ul><li>terser-webpack-plugin 开启 cache</li><li>babel-loader 开启 cache</li><li>使用 cache-loader ，耗时的 loader 之前使用</li><li>hard-source-webpack-plugin，构建缓存二次构建时间减少 80%</li></ul></li></ul><p>vue-cli4 默认配置已经添加了很多优化，包括：</p><ul><li>teser-webpack-plugin 代码压缩，且开启 parallel 和 cache 选项</li><li>thread-loader 多线程： 为 babel-loader 开启了多线程</li><li>cache-loader 缓存： 为 babel-loader 和 vue-loader 都开启了缓存</li><li>eslint-loader：开启 cache 选项</li><li>url-loader：小于 4K 的图片会转 base64</li><li>mini-css-extract-plugin，提取css</li><li>preload-webpack-plugin：入口加上preload，按需加载文件加上prefetch</li></ul><h2 id="_4-vue-有哪些优化手段" tabindex="-1">4. Vue 有哪些优化手段 <a class="header-anchor" href="#_4-vue-有哪些优化手段" aria-label="Permalink to &quot;4. Vue 有哪些优化手段&quot;">​</a></h2><ul><li>Object.freeze() 常量</li><li>v-if/v-show 切换频繁使用v-show</li><li>v-for 使用唯一的 key</li><li>使用 computed</li><li>keep-alive 缓存</li><li>路由懒加载</li><li>虚拟列表/懒加载</li></ul><p>坑和最佳实践：</p><ul><li><p>不要在同一个元素上使用 v-for 和 v-if</p></li><li><p>生命周期里解除对应的事件监听</p></li><li><p>响应式缺陷：新增属性，数组下标 <code>this.$set</code></p></li><li><p><code>this.$forceUpdate()</code>：重新执行render函数</p></li><li><p>使用变化的key 使组件重新加载</p></li><li><p>使用<code>Object.assign(this.$data, this.$options.data())</code> 重置data</p></li><li><p>watch中使用<code>immediate:true</code>，执行时机是在<code>created</code>之前，不用在<code>created</code>再执行</p></li></ul>',33))])}const T=a(s,[["render",n]]);export{_ as __pageData,T as default};
